// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(baseURL+"/admin/articles", wrapper.ListAdminArticles)
	router.GET(baseURL+"/admin/comments", wrapper.ListAdminComments)
	router.POST(baseURL+"/admin/comments/:id/approve", wrapper.ApproveComment)
	router.POST(baseURL+"/admin/comments/:id/reject", wrapper.RejectComment)
	router.GET(baseURL+"/admin/dashboard", wrapper.GetAdminDashboard)
	router.GET(baseURL+"/admin/projects", wrapper.ListAdminProjects)
	router.GET(baseURL+"/articles", wrapper.ListArticles)
	router.POST(baseURL+"/articles", wrapper.CreateArticle)
	router.GET(baseURL+"/articles/archive", wrapper.ListArticleArchive)
	router.DELETE(baseURL+"/articles/:slug", wrapper.DeleteArticle)
	router.GET(baseURL+"/articles/:slug", wrapper.GetArticle)
	router.PUT(baseURL+"/articles/:slug", wrapper.UpdateArticle)
	router.GET(baseURL+"/articles/:slug/comments", wrapper.ListArticleComments)
	router.POST(baseURL+"/articles/:slug/comments", wrapper.CreateComment)
	router.PUT(baseURL+"/articles/:slug/like", wrapper.SetArticleLike)
	router.GET(baseURL+"/articles/:slug/like/status", wrapper.GetArticleLikeStatus)
	router.POST(baseURL+"/articles/:slug/publish", wrapper.PublishArticle)
	router.POST(baseURL+"/articles/:slug/top", wrapper.SetArticleTop)
	router.POST(baseURL+"/articles/:slug/unpublish", wrapper.UnpublishArticle)
	router.POST(baseURL+"/auth/login", wrapper.Login)
	router.POST(baseURL+"/auth/logout", wrapper.Logout)
	router.GET(baseURL+"/auth/me", wrapper.GetCurrentUser)
	router.POST(baseURL+"/auth/refresh", wrapper.RefreshAccessToken)
	router.GET(baseURL+"/categories", wrapper.ListCategories)
	router.POST(baseURL+"/categories", wrapper.CreateCategory)
	router.DELETE(baseURL+"/categories/:slug", wrapper.DeleteCategory)
	router.GET(baseURL+"/categories/:slug", wrapper.GetCategory)
	router.PUT(baseURL+"/categories/:slug", wrapper.UpdateCategory)
	router.DELETE(baseURL+"/comments/:id", wrapper.DeleteComment)
	router.GET(baseURL+"/healthz", wrapper.GetHealth)
	router.GET(baseURL+"/projects", wrapper.ListProjects)
	router.POST(baseURL+"/projects", wrapper.CreateProject)
	router.DELETE(baseURL+"/projects/:slug", wrapper.DeleteProject)
	router.GET(baseURL+"/projects/:slug", wrapper.GetProject)
	router.PUT(baseURL+"/projects/:slug", wrapper.UpdateProject)
	router.GET(baseURL+"/readyz", wrapper.GetReady)
	router.GET(baseURL+"/rss.xml", wrapper.GetRss)
	router.GET(baseURL+"/site/settings", wrapper.GetSiteSettings)
	router.PUT(baseURL+"/site/settings", wrapper.UpdateSiteSettings)
	router.GET(baseURL+"/site/stats", wrapper.GetSiteStats)
	router.GET(baseURL+"/sitemap.xml", wrapper.GetSitemap)
	router.GET(baseURL+"/tags", wrapper.ListTags)
	router.POST(baseURL+"/tags", wrapper.CreateTag)
	router.DELETE(baseURL+"/tags/:slug", wrapper.DeleteTag)
	router.GET(baseURL+"/tags/:slug", wrapper.GetTag)
	router.PUT(baseURL+"/tags/:slug", wrapper.UpdateTag)
	router.POST(baseURL+"/upload/image", wrapper.UploadImage)

}

